#include <bits/stdc++.h>
using namespace std;

void solve(istream& in, ostream& out) {
    // Đọc dữ liệu từ `in` (dùng như cin), in kết quả ra `out` (dùng như cout).
    // (Ghép bài thực tế: chương trình thi đọc từ bàn phím / tệp — ở đây
    //  để chấm tự động, dữ liệu vào/ra đi qua hai luồng này.)
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}

